from pathlib import Path
import json,hashlib,os
p=Path.cwd();baseline=json.loads((p/'evidence/baseline.json').read_text());pins=json.loads((p/'evidence/composition-inputs.json').read_text());ledger=json.loads((p/'evidence/source-ledger.json').read_text());up=Path(pins['upstream'])
def sha(f):return hashlib.sha256(f.read_bytes()).hexdigest()
def files(root):return {str(f.relative_to(root)):sha(f) for f in root.rglob('*') if f.is_file()}
checks={'candidate_source_exact':files(p/'src')==ledger['source'],'original_actual105_exact':files(Path(baseline['actual_sdk']))==baseline['files'],'original_recovery105_exact':files(p/'baseline/src')==baseline['files'],'upstream106_exact':files(up/'src')==pins['upstream_source'],'upstream_recovery106_exact':files(p/'baseline/upstream-src')==pins['upstream_source'],'prior35_test_exact':sha(p/'tests/market.test.ts')==pins['prior35_test_sha256'],'guard181_exact':all(Path(f).is_file() and sha(Path(f))==h for f,h in baseline['installed_before'].items()),'four_abi_exact':all(sha(Path(v['path']))==v['sha256'] for v in pins['abi'].values()),'current_and_governance_exact':all(sha(Path(f))==h for f,h in pins['protected_before'].items()),'package_pins_exact':all(sha(p/f)==h for f,h in baseline['dependency_pins'].items()),'runtime_packages_exact':all(sha(Path(v['path']))==v['sha256'] for v in pins['runtime'].values()),'source_has_no_symlink':not any(f.is_symlink() for f in (p/'src').rglob('*')),'baseline_has_no_symlink':not any(f.is_symlink() for f in (p/'baseline').rglob('*')),'runtime_is_only_symlink':sorted(str(f.relative_to(p)) for f in p.rglob('*') if f.is_symlink())==['node_modules']}
print(json.dumps({'checks':checks,'all_pass':all(checks.values()),'source_count':len(ledger['source']),'guard_count':len(baseline['installed_before'])},indent=2));assert all(checks.values())
